        BigDecimal totalTax = BigDecimal.ZERO;
        for (Reservation res : monthReservations) {
            BigDecimal tax = TOURISM_TAX_PER_GUEST_PER_NIGHT
                    .multiply(new BigDecimal(res.getGuests()))
                    .multiply(new BigDecimal(res.getNights()));
