            put("total", formatPrice(res.getTotal()));
            put("status", res.getStatus().toString());
            put("amountPaid", formatPrice(res.getAmountPaid()));
            put("refund", res.getRefund() != null ? formatPrice(res.getRefund()) : null);
        }};
    }

